ContractView012 = build_contract_view([{'api_id': 'API-FHIR-009', 'app': 'integrations', 'domain': 'FHIR R4', 'api_name': 'FHIR MedicationRequest 검색', 'method': 'GET', 'endpoint': '/fhir/R4/MedicationRequest', 'django_path': 'fhir/R4/MedicationRequest', 'roles': [], 'permission': None, 'service_scope': 'fhir.read', 'request_contract': 'Path: -\nQuery: patient: Patient/{id}, 필수\nstatus: active|completed|cancelled|stopped, 선택\nauthoredon: FHIR date prefix, 선택\n_count: 1~100\nBody: -', 'validation': 'mTLS 또는 Service JWT + SERVICE_SCOPE:fhir.read\n• patient 필수\n• 원본 검색 계약의 active|completed|cancelled|stopped 이름은 유지\n• 현재 확정 Prescription.status는 DRAFT|FINAL만 존재\n• 따라서 active/completed만 현재 DB에서 정확히 파생 가능\n• cancelled/stopped 요청은 임의로 0건 처리하지 않고 FHIR_INVALID_SEARCH(400)로 명시적으로 거절', 'related_db': 'Prescription (prescriptions) / PrescriptionItem (prescription_items)\nIntegrationTransaction (interoperability_integrationtransaction)\nAuditLog (audit_auditlog)', 'processing': '• FINAL Prescription의 PrescriptionItem을 MedicationRequest로 변환(항목 1개당 1 Resource)\n• active: today가 start_date 이상이고 start_date+duration_days-1 이하\n• completed: today가 종료일보다 이후\n• DRAFT는 외부 FHIR 검색에서 제외\n• cancelled/stopped는 현재 DB Source lifecycle이 없어 400 OperationOutcome 반환\n• DUR Alert 상세는 별도 Extension 정책 적용\n• IntegrationTransaction·AuditLog 기록', 'response_contract': 'FHIR Bundle(type=searchset), entry[].resource=MedicationRequest', 'success': '200 OK', 'error_contract': 'FHIR_AUTH_REQUIRED(401)\nFHIR_FORBIDDEN(403)\nFHIR_INVALID_SEARCH(400 → OperationOutcome; cancelled/stopped 포함 현재 미지원 status)', 'transaction': 'X(업무 데이터 조회 전용; Audit/Integration 기록은 별도 로깅 트랜잭션)', 'transactional': False, 'event': '-', 'note': '권한유형: SERVICE_SCOPE(fhir.read) / mTLS 또는 Service JWT, DB Role 미사용', 'primary_model': 'integrations.IntegrationTransaction', 'audit_required': True}])
